5	@function fluid($y1, $y2, $x1: 375, $x2: 1920) {
6	  // font-size: clamp([min]rem, [v]vw + [r]rem, [max]rem);
7	
8	  // font-size: clamp(2.25rem, 2vw + 1.5rem, 3.25rem);
9	
10	  // y = v / 100 * x + r
11	
12	  // y1 : 최소글꼴크기 ex) 36px
13	
14	  // y2 : 최대글꼴크기 ex) 52px
15	
16	  // x1: 최소화면크기 ex) 600px
17	
18	  // x2: 최대화면크기 ex) 1400px
19	
20	  // test
21	
22	  // $y1: 36;
23	
24	  // $y2: 52;
25	
26	  // $x1: 600;
27	
28	  // $x2: 1400;
29	
30	  @if ($x1 == null) {
31	    $x1: 375;
32	  }
33	
34	  @if ($x2 == null) {
35	    $x2: 1920;
36	  }
37	
38	  $v: math.div(($y2 - $y1) * 100, $x2 - $x1);
39	
40	  $r: math.div(($x1 * $y2) - ($x2 * $y1), ($x1 - $x2));
41	
42	  $min: $y1 * 0.1rem;
43	
44	  $base: $r * 0.1rem;
45	
46	  $max: $y2 * 0.1rem;
47	
48	  $vw: $v * 1vw;
49	
50	  @return clamp($min, $vw + $base, $max);
51	}
52	
53	@function minus-fluid($y1, $y2, $x1: 375, $x2: 1920) {
54	  @if ($x1 == null) {
55	    $x1: 375;
56	  }
57	
58	  @if ($x2 == null) {
59	    $x2: 1920;
60	  }
61	
62	  $v: math.div(($y2 - $y1) * 100, $x2 - $x1);
63	
64	  $r: math.div(($x1 * $y2) - ($x2 * $y1), ($x1 - $x2));
65	
66	  $min: $y1 * 0.1rem;
67	
68	  $base: $r * 0.1rem;
69	
70	  $max: $y2 * 0.1rem;
71	
72	  $vw: $v * 1vw;
73	
74	  @return clamp(-#{$min}, -#{$vw} + -#{$base}, -#{$max});
75	}
76	
77	@function pxToRem($px) {
78	  // 35 => 3.5rem
79	
80	  @return $px * 0.1rem;
81	}
