292	@mixin font($name) {
293	  $without-prefix: string.slice($name, 3);
294	  $last-dash-idx: 0;
295	
296	  @for $i from 1 through string.length($without-prefix) {
297	    @if string.slice($without-prefix, $i, $i) == "-" {
298	      $last-dash-idx: $i;
299	    }
300	  }
301	
302	  $category: string.slice($without-prefix, 1, $last-dash-idx - 1);
303	  $key: string.slice($without-prefix, $last-dash-idx + 1);
304	
305	  $type-map: map.get(heading.$fluid-typography, $category);
306	
307	  @if ($type-map == null) {
308	    @error "Unknown font category '#{$category}' in '#{$name}'";
309	  }
310	
311	  $val: map.get($type-map, $key);
312	
313	  @if ($val == null) {
314	    @error "Unknown font key '#{$key}' in category '#{$category}'";
315	  }
316	
317	  @include fs-fluid-by-map($val);
318	}
